// ── CONFIGURAÇÃO ──────────────────────────────────────────
// Ajuste o caminho base onde seus arquivos .md estão salvos
const BASE_PATH = '/data/relatorios-clientes';
// Extensão dos arquivos (mude para '.MD' se necessário)
const FILE_EXT = '.md';
// ──────────────────────────────────────────────────────────

const body = $input.first().json.body ?? $input.first().json;
const customerId = body?.customerId;

if (!customerId) {
  throw new Error('INVALID_INPUT: customerId é obrigatório no body da requisição');
}

// Sanitiza o ID: permite apenas letras, números, underscore e hífen
const sanitized = String(customerId).replace(/[^a-zA-Z0-9_-]/g, '');

if (!sanitized || sanitized.length === 0) {
  throw new Error('INVALID_INPUT: customerId contém apenas caracteres inválidos');
}

if (sanitized.length > 100) {
  throw new Error('INVALID_INPUT: customerId muito longo (máximo 100 caracteres)');
}

return [{
  json: {
    customerId: sanitized,
    filePath: `${BASE_PATH}/${sanitized}${FILE_EXT}`,
    requestedAt: new Date().toISOString(),
    teamId: body?.teamId ?? null,
    channelId: body?.channelId ?? null
  }
}];

const fileItem = $input.first();
const meta = $('Validar e Construir Caminho').first().json;

// Decodifica o conteúdo binário do arquivo
const binaryKey = Object.keys(fileItem.binary ?? {})[0];
if (!binaryKey) {
  throw new Error('FILE_READ_ERROR: Nenhum conteúdo encontrado no arquivo');
}

const rawContent = Buffer.from(fileItem.binary[binaryKey].data, 'base64').toString('utf-8');

// Limite do Teams para mensagens de texto: ~28.000 caracteres
const MAX_CHARS = 25000;
const isTruncated = rawContent.length > MAX_CHARS;
const content = isTruncated ? rawContent.substring(0, MAX_CHARS) : rawContent;

// Converte Markdown básico em HTML compatível com Teams
function mdToTeamsHtml(md) {
  return md
    // Títulos
    .replace(/^#### (.+)$/gm, '<h4>$1</h4>')
    .replace(/^### (.+)$/gm, '<h3>$1</h3>')
    .replace(/^## (.+)$/gm, '<h2>$1</h2>')
    .replace(/^# (.+)$/gm, '<h1>$1</h1>')
    // Negrito e itálico
    .replace(/\*\*\*(.+?)\*\*\*/g, '<strong><em>$1</em></strong>')
    .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
    .replace(/\*(.+?)\*/g, '<em>$1</em>')
    // Código inline
    .replace(/`(.+?)`/g, '<code>$1</code>')
    // Listas
    .replace(/^[-*] (.+)$/gm, '&nbsp;&nbsp;• $1')
    .replace(/^\d+\. (.+)$/gm, (m, p1, offset, str) => {
      const num = m.match(/^(\d+)/)[1];
      return `&nbsp;&nbsp;${num}. ${p1}`;
    })
    // Separadores
    .replace(/^---+$/gm, '<hr/>')
    // Quebras de linha
    .replace(/\n/g, '<br/>');
}

const htmlContent = mdToTeamsHtml(content);

// Formata timestamp para horário de Brasília (UTC-3)
const now = new Date();
const brTime = now.toLocaleString('pt-BR', {
  timeZone: 'America/Sao_Paulo',
  day: '2-digit', month: '2-digit', year: 'numeric',
  hour: '2-digit', minute: '2-digit'
});

const warningBanner = isTruncated
  ? '<br/><br/><strong>⚠️ Relatório truncado</strong> — O arquivo completo excede o limite do Teams. Acesse o arquivo original para mais detalhes.<br/>'
  : '';

const fullMessage = [
  `<h2>📊 Relatório de Vendas — Cliente ${meta.customerId}</h2>`,
  '<hr/>',
  htmlContent,
  warningBanner,
  '<hr/>',
  `<small>🕐 Gerado em: ${brTime} | Arquivo: ${meta.filePath}</small>`
].join('');

return [{
  json: {
    customerId: meta.customerId,
    teamId: meta.teamId,
    channelId: meta.channelId,
    message: fullMessage,
    charCount: rawContent.length,
    isTruncated,
    requestedAt: meta.requestedAt
  }
}];

const error = $input.first().json;
const errorMsg = error.error?.message ?? 'Erro desconhecido';

let userMessage = '';
let statusCode = 500;

if (errorMsg.includes('INVALID_INPUT')) {
  const detail = errorMsg.replace('INVALID_INPUT: ', '');
  userMessage = `<strong>❌ Requisição inválida</strong><br/>${detail}`;
  statusCode = 400;
} else if (errorMsg.includes('ENOENT') || errorMsg.includes('no such file')) {
  // Extrai o customer ID do caminho do erro
  const pathMatch = errorMsg.match(/\/([^\/]+)\.md/);
  const clientId = pathMatch ? pathMatch[1] : 'desconhecido';
  userMessage = `<strong>🔍 Cliente não encontrado</strong><br/>Nenhum relatório localizado para o ID: <code>${clientId}</code><br/><br/>Verifique se o ID está correto e se o arquivo existe.`;
  statusCode = 404;
} else {
  userMessage = `<strong>⚠️ Erro interno</strong><br/>Não foi possível processar o relatório.<br/><br/><code>${errorMsg}</code>`;
}

return [{
  json: {
    teamsMessage: userMessage,
    statusCode,
    originalError: errorMsg
  }
}];
